{
  "county_id": "HVA14",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The optimiser picked timed-pathways for North Karelia wellbeing services county at EUR 242,127 a year, with a model scenario of 7.8 deaths postponed per year (range 1.2-15.6) and the action stayed in 92% of sensitivity runs; the county's specialist wait over 6 months is 79.3 per 10 000 against 36 nationally.",
      "owner_role": "Wellbeing services county, coordinated nationally by FICAN",
      "indicator": "Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended.",
      "rationale": "Cervical screening participation in North Karelia wellbeing services county is 66.4% against the 80% target, and the portfolio assigns self-sampling an assumed cost of EUR 96,851 a year with an expected gain of 1.5-4.5 percentage points, closing about 22% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in North Karelia wellbeing services county is 75.9% against the 80% target, and the portfolio assigns screening-reminders an assumed cost of EUR 64,567 a year with an expected gain of 1.5-4.07 percentage points, closing about 74% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support that these actions will reduce cancer mortality in North Karelia wellbeing services county: the timed-pathways mortality estimate is a model scenario under stated assumptions, Danish pathway evidence is before/after without a control group, and the screening gains are expected gains from Finnish trial evidence rather than measured county effects."
}

